def process_command(cmd, gui=None):
    if not cmd:
        if gui: gui.is_processing = False
        return

    # ★ V82: Kısa komutları önce yakala (hız için)
    t_short = cmd.lower().strip()
    if len(t_short) < 15:
        # Kısa komutlar için hızlı yol
        if ag_koruma.yasakli_mi(t_short):
            _yanit(gui, "Efendim, bu komut güvenlik nedeniyle engellendi.")
            return
